# openEMS model generated by OpenBoard (RF PCB). Requires openEMS + CSXCAD Python bindings.
import os, numpy as np
from CSXCAD import ContinuousStructure
from openEMS import openEMS
from openEMS.physical_constants import C0
unit = 1e-3; f_max = 10e9; f0 = f_max / 2; fc = f_max / 2
FDTD = openEMS(NrTS=60000, EndCriteria=1e-4)
FDTD.SetGaussExcite(f0, fc)
FDTD.SetBoundaryCond(['PML_8'] * 6)
CSX = ContinuousStructure()
FDTD.SetCSX(CSX)
mesh = CSX.GetGrid(); mesh.SetDeltaUnit(unit)
metal = CSX.AddMetal("copper")
sub0 = CSX.AddMaterial("diel0", epsilon=4.4, kappa=2.4478e-2)
sub0.AddBox([0, 0, 0.035], [60.4, 59.3, 1.565], priority=0)
metal.AddLinPoly(points=np.array([[24.2, 36.2, 36.2, 32.2, 32.2, 57.4, 57.4, 28.2, 28.2, 24.2], [56.3, 56.3, 44.7, 11.6, 10.6, 10.6, 3, 3, 11.6, 44.7]]), norm_dir='z', elevation=0, length=0.035, priority=10)  # 0
metal.AddLinPoly(points=np.array([[28.795, 31.605, 31.605, 32.2, 32.2, 3, 3, 28.2, 28.2, 28.795], [54.1, 54.1, 44.7, 11.6, 3, 3, 10.6, 10.6, 11.6, 44.7]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 1
metal.AddLinPoly(points=np.array([[32.605, 36.2, 36.2, 32.605], [56.3, 56.3, 49.7, 49.7]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 2
metal.AddLinPoly(points=np.array([[24.2, 27.795, 27.795, 24.2], [56.3, 56.3, 49.7, 49.7]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 3
metal.AddLinPoly(points=np.array([[28.6, 31.8, 31.8, 28.6], [53.465, 53.465, 54.735, 54.735]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 4
metal.AddLinPoly(points=np.array([[31.175, 34.875, 34.875, 31.175], [53.675, 53.675, 55.025, 55.025]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 5
metal.AddLinPoly(points=np.array([[31.175, 34.875, 34.875, 31.175], [53.675, 53.675, 55.025, 55.025]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 6
metal.AddLinPoly(points=np.array([[25.525, 29.225, 29.225, 25.525], [53.675, 53.675, 55.025, 55.025]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 7
metal.AddLinPoly(points=np.array([[25.525, 29.225, 29.225, 25.525], [53.675, 53.675, 55.025, 55.025]]), norm_dir='z', elevation=1.565, length=0.035, priority=10)  # 8
metal.AddLinPoly(points=np.array([[31.175, 34.875, 34.875, 31.175], [53.675, 53.675, 55.025, 55.025]]), norm_dir='z', elevation=0, length=0.035, priority=10)  # 9
metal.AddLinPoly(points=np.array([[25.525, 29.225, 29.225, 25.525], [53.675, 53.675, 55.025, 55.025]]), norm_dir='z', elevation=0, length=0.035, priority=10)  # 10
port1 = FDTD.AddLumpedPort(1, 50, [29.565, 53.465, 0.035], [30.835, 54.735, 1.565], 'z', excite=1, priority=20)  # J1-1
mesh.AddLine('x', [0, 60.4]); mesh.AddLine('y', [0, 59.3]); mesh.AddLine('z', [-3, 4.6])
mesh.AddLine('z', [1.565, 1.6, 0, 0.035])
for d in 'xyz':
    mesh.SmoothMeshLines(d, C0 / f_max / unit / 20, 1.4)
sim = os.path.join(os.getcwd(), 'openboard_rf')
FDTD.Run(sim, cleanup=True)
f = np.linspace(max(1e6, f0 - fc), f0 + fc, 401)
for prt in [p for p in [globals().get("port%d" % i) for i in range(1, 9)] if p is not None]: prt.CalcPort(sim, f)
s11 = port1.uf_ref / port1.uf_inc
out = ["# Hz S RI R 50"] + ["%g %g %g" % (fi, s.real, s.imag) for fi, s in zip(f, s11)]
if 'port2' in globals(): s21 = port2.uf_ref / port1.uf_inc; out = ["# Hz S RI R 50"] + ["%g %g %g %g %g %g %g %g %g" % (fi, a.real, a.imag, b.real, b.imag, b.real, b.imag, a.real, a.imag) for fi, a, b in zip(f, s11, s21)]
open('openboard_rf.s%dp' % (2 if 'port2' in globals() else 1), 'w').write('\n'.join(out))
